from system.message import BaseMessageDataType
from model.strategy_type import StrategyType
from model.base import BaseStrategy
import random

class ExclusivityParticlesCustomStrategy:
    def __init__(self, model: BaseStrategy):
        self._model = model
        self.name = self._model.name
        self.history = self._model.history
        self.strategy_type = StrategyType.Custom

    def update_model_field(self, field_name: str, value: Any):
        if hasattr(self._model, field_name):
            setattr(self._model, field_name, value)

    def receive_message(self, message: Info) -> Info:
        data = message.message[0].data
        dimension = data['dimension']
        distance = data['distance']
        cnt_particles = data['particles']

        def hamming(a: List[int], b: List[int]) -> int:
            return sum(x ^ y for x, y in zip(a, b))

        def is_valid(candidate: List[int]) -> bool:
            for p in cnt_particles:
                if hamming(candidate, p) < distance:
                    return False
            return True

        next_particle: Optional[List[int]] = None

        # 1) If first move, pick all zeros
        if not cnt_particles:
            next_particle = [0] * dimension
        else:
            # 2) Try structured candidates
            # all zeros
            cand = [0] * dimension
            if is_valid(cand):
                next_particle = cand
            # all ones
            if next_particle is None:
                cand = [1] * dimension
                if is_valid(cand):
                    next_particle = cand
            # prefix-one patterns and complements
            if next_particle is None:
                for i in range(1, dimension):
                    cand = [1] * i + [0] * (dimension - i)
                    if is_valid(cand):
                        next_particle = cand
                        break
                    inv = [1 - bit for bit in cand]
                    if is_valid(inv):
                        next_particle = inv
                        break
            # 3) Random sampling
            if next_particle is None:
                trials = 1000
                for _ in range(trials):
                    cand = [random.randint(0, 1) for _ in range(dimension)]
                    if is_valid(cand):
                        next_particle = cand
                        break

        # 4) If no valid found, next_particle remains None
        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=next_particle, type='custom')]
        )

