        data = message.message[0].data
        dimension = data['dimension']
        distance = data['distance']
        cnt_particles = data['particles']

        # Helper to convert list of bits to integer mask
        def bits_to_int(bits: List[int]) -> int:
            mask = 0
            for b in bits:
                mask = (mask << 1) | (b & 1)
            return mask

        # Helper to convert integer mask back to list of bits
        def int_to_bits(x: int) -> List[int]:
            bits = [(x >> i) & 1 for i in range(dimension - 1, -1, -1)]
            return bits

        # Precompute existing masks
        existing_masks = set()
        for p in cnt_particles:
            existing_masks.add(bits_to_int(p))

        next_particle = None
        total_states = 1 << dimension

        # If first move, play all zeros
        if not existing_masks:
            next_particle = [0] * dimension
        else:
            # Distance check against all existing
            def is_valid(mask: int) -> bool:
                for em in existing_masks:
                    # Hamming distance = popcount of XOR
                    if (mask ^ em).bit_count() < distance:
                        return False
                return True

            # Random sampling
            sampled = set()
            max_trials = min(5000, total_states)
            for _ in range(max_trials):
                mask = random.getrandbits(dimension)
                # Mask off any higher bits
                mask &= (total_states - 1)
                if mask in existing_masks or mask in sampled:
                    continue
                sampled.add(mask)
                if is_valid(mask):
                    next_particle = int_to_bits(mask)
                    break

            # If random failed, do exhaustive if feasible
            if next_particle is None and total_states <= 10**6:
                for mask in range(total_states):
                    if mask in existing_masks or mask in sampled:
                        continue
                    if is_valid(mask):
                        next_particle = int_to_bits(mask)
                        break

        # If we still have no move, return None
        if next_particle is None:
            result = None
        else:
            result = next_particle

        return Info(
            sender=self.__class__.__name__,
            receiver=message.sender,
            difficulty=message.difficulty,
            message=[BaseMessageDataType(data=result, type='custom')]
        )

